<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_student();$uid=(int)current_user()['user_id'];$q=trim((string)($_GET['q']??''));$type=$_GET['type']??'';$cat=(int)($_GET['category_id']??0);$where=['t.user_id=?','t.status="active"'];$params=[$uid];if(in_array($type,['income','expense'],true)){$where[]='t.type=?';$params[]=$type;}if($cat){$where[]='t.category_id=?';$params[]=$cat;}if($q!==''){$where[]='(t.description LIKE ? OR c.name LIKE ?)';$params[]="%$q%";$params[]="%$q%";}$s=db()->prepare('SELECT t.*,c.name category FROM transactions t JOIN categories c ON c.category_id=t.category_id WHERE '.implode(' AND ',$where).' ORDER BY t.transaction_date DESC,t.transaction_id DESC');$s->execute($params);$rows=$s->fetchAll();$cats=array_merge(user_categories($uid,'income'),user_categories($uid,'expense'));$pageTitle='Transactions';$activePage='transactions';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow"><i></i> LEDGER</span><h1>Your transactions</h1><p>Search, filter and edit your full active ledger. Deleted records remain in history.</p></div><a class="btn btn-primary" href="<?=e(url('student/add-transaction.php'))?>">＋ Add transaction</a></section><section class="panel"><form class="filter-bar"><input class="input" name="q" placeholder="Search..." value="<?=e($q)?>"><select class="input" name="type"><option value="">All types</option><option value="income" <?=$type==='income'?'selected':''?>>Income</option><option value="expense" <?=$type==='expense'?'selected':''?>>Expense</option></select><select class="input" name="category_id"><option value="0">All categories</option><?php foreach($cats as$c):?><option value="<?=$c['category_id']?>" <?=$cat===$c['category_id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button><a class="btn btn-ghost" href="<?=e(url('student/transactions.php'))?>">Reset</a></form></section><section class="panel table-panel"><div class="panel-head"><div><span class="panel-kicker"><?=count($rows)?> RECORDS</span><h2>Transaction ledger</h2></div><span><a href="<?=e(url('student/recurring.php'))?>">Recurring →</a> &nbsp; <a href="<?=e(url('student/import.php'))?>">Import CSV →</a></span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Type</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=e(date('d M Y',strtotime($r['transaction_date'])))?></td><td><?=e($r['description']?:'—')?></td><td><span class="tag"><?=e($r['category'])?></span></td><td><span class="status <?=$r['type']==='income'?'income':'expense'?>"><?=e(ucfirst($r['type']))?></span></td><td class="<?=$r['type']==='income'?'text-green':'text-red'?>"><?=$r['type']==='income'?'+':'-'?><?=money($r['amount'])?></td><td><a class="action-link" href="<?=e(url('student/edit-transaction.php?id='.$r['transaction_id']))?>">Edit</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state">No matching transactions.</div></td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>